from __future__ import annotations

import base64
import secrets

from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.padding import PKCS7

ALGORITHM_ID = "f0a940"
IV_SEPARATOR = "îvïv"

# The Android app selects a 32-character hex IV from a much larger embedded
# lookup string and sends its offset with the ciphertext. This confirmed prefix
# provides 33 valid app-compatible IVs without copying the entire 10 KiB table.
IV_STASH = ""


class ModCryptoError(ValueError):
    pass


def encode_payload(value: str, key_hex: str, *, response: bool = False) -> str:
    key = _parse_key(key_hex)
    offset = secrets.randbelow(len(IV_STASH) - 31)
    iv = bytes.fromhex(IV_STASH[offset : offset + 32])

    if response:
        value = base64.b64encode(value.encode("utf-8")).decode("ascii")
    padder = PKCS7(128).padder()
    padded = padder.update(value.encode("utf-8")) + padder.finalize()
    encryptor = Cipher(algorithms.AES(key), modes.CBC(iv)).encryptor()
    ciphertext = encryptor.update(padded) + encryptor.finalize()

    # CryptoJS.toString() returns Base64 text. The app then Base64-encodes that
    # UTF-8 text once more before prefixing the algorithm and IV locator.
    encoded = base64.b64encode(ciphertext)
    if not response:
        encoded = base64.b64encode(encoded)
    return f"{ALGORITHM_ID}{offset}{IV_SEPARATOR}{encoded.decode('ascii')}"


def decode_payload(value: str, key_hex: str, *, response: bool = False) -> str:
    key = _parse_key(key_hex)
    if not value.startswith(ALGORITHM_ID):
        raise ModCryptoError("The encrypted response uses an unknown algorithm.")

    remainder = value[len(ALGORITHM_ID) :]
    separator_at = remainder.find(IV_SEPARATOR)
    if separator_at < 1:
        raise ModCryptoError("The encrypted response has no valid IV locator.")
    try:
        offset = int(remainder[:separator_at])
        iv_hex = IV_STASH[offset : offset + 32]
        if len(iv_hex) != 32:
            raise ValueError
        iv = bytes.fromhex(iv_hex)
        decoded = base64.b64decode(
            remainder[separator_at + len(IV_SEPARATOR) :], validate=True
        )
        ciphertext = decoded if response else base64.b64decode(decoded, validate=True)
    except (ValueError, UnicodeError) as error:
        raise ModCryptoError("The encrypted response has an invalid encoding.") from error

    try:
        decryptor = Cipher(algorithms.AES(key), modes.CBC(iv)).decryptor()
        padded = decryptor.update(ciphertext) + decryptor.finalize()
        unpadder = PKCS7(128).unpadder()
        plaintext = unpadder.update(padded) + unpadder.finalize()
        if response:
            plaintext = base64.b64decode(plaintext, validate=True)
        return plaintext.decode("utf-8")
    except (ValueError, UnicodeError) as error:
        raise ModCryptoError("The encrypted response could not be decrypted.") from error


def _parse_key(key_hex: str) -> bytes:
    try:
        key = bytes.fromhex(key_hex)
    except ValueError as error:
        raise ModCryptoError("The stored encryption key is invalid.") from error
    if len(key) not in (16, 24, 32):
        raise ModCryptoError("The stored encryption key has an invalid length.")
    return key
